function quorumMet(acksReceived, W) {
  return acksReceived >= W;
}

function writeQuorum(nodes, W) {
  let acks = 0;
  for (const node of nodes) {
    if (node.write(value)) acks++;
    if (quorumMet(acks, W)) return "write succeeded";
  }
  return "write failed, quorum not reached";
}

// Example: N = 5, W = 3, R = 3
// W + R = 6 > N = 5, so every read quorum overlaps every write quorum

